	}

	fields := m.fields()
	if len(fields) == 0 {
		return m, cmd
	}
	m.focusedField = m.settleFocus((m.focusedField+step+len(fields))%len(fields), step)
	m.bindInput()
	return m, cmd
}","merged_ranks":[2,3]},{"rank":3,"score":37.5023,"file_path":"internal/ui/components/confirm_modal.go","start_line":22,"end_line":28,"focus_line":22,"snippet_start_line":22,"snippet_end_line":28,"symbol_start_line":22,"symbol_end_line":28,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/ui/components/confirm_modal.go:function:NewConfirmModal","symbol_name":"NewConfirmModal","qualified_name":"NewConfirmModal","signature":"func NewConfirmModal(title, message string) *ConfirmModal","signals":["graph:calls","graph:outgoing","graph:callers","complete-symbol"],"snippet":"func NewConfirmModal(title, message string) *ConfirmModal {
